// Webhook payload fixtures shaped verbatim from GitHub's official webhook
// docs (docs.github.com/en/webhooks/webhook-events-and-payloads): the
// `issues`, `issue_comment`, `pull_request`, `pull_request_review`,
// `pull_request_review_comment`, `status` and `check_suite` examples,
// trimmed to the fields the normalizer reads (unknown fields are ignored by
// BOTH GitHub and us, so trimming is lossless for the contract). The e2e
// signs these with the real HMAC scheme and posts them to the kernel sink.
import { createHmac } from "node:crypto";

export const WEBHOOK_SECRET = "gh-wh-secret";

/** The real wire scheme: `sha256=<hex HMAC-SHA256 over the raw body>`. */
export function sign(body: string, secret: string = WEBHOOK_SECRET): string {
  return `sha256=${createHmac("sha256", secret).update(body, "utf8").digest("hex")}`;
}

const repo = {
  id: 1296269,
  node_id: "MDEwOlJlcG9zaXRvcnkxMjk2MjY5",
  name: "Hello-World",
  full_name: "octocat/Hello-World",
  owner: { login: "octocat", id: 1, node_id: "MDQ6VXNlcjE=", type: "User" },
  private: false,
  html_url: "https://github.com/octocat/Hello-World",
  url: "https://api.github.com/repos/octocat/Hello-World",
};

const sender = {
  login: "octocat",
  id: 1,
  node_id: "MDQ6VXNlcjE=",
  type: "User",
  site_admin: false,
};

function issue(number: number, labels: { id: number; name: string }[], body: string): unknown {
  return {
    id: 1386,
    node_id: "MDU6SXNzdWUxMzg2",
    url: `https://api.github.com/repos/octocat/Hello-World/issues/${String(number)}`,
    number,
    state: "open",
    title: "Fundable human review path",
    body,
    labels,
    comments: 0,
    created_at: "2011-04-22T13:33:48Z",
    updated_at: "2011-04-22T13:33:48Z",
    user: sender,
  };
}

