function pullRequest(number: number, headRef: string, merged = false): unknown {
  return {
    id: 3671,
    node_id: "MDExOlB1bGxSZXF1ZXN0MzY3MQ==",
    url: `https://api.github.com/repos/octocat/Hello-World/pulls/${String(number)}`,
    number,
    state: merged ? "closed" : "open",
    title: "Add release-notes table",
    body: "Generated by the facilitator worker.",
    merged,
    head: {
      label: `headowner:${headRef}`,
      ref: headRef,
      sha: "sha-head-0123456789abcdef",
      repo,
    },
    base: { label: "octocat:master", ref: "master", sha: "sha-base-0123456789abcdef", repo },
    user: sender,
  };
}

